// Compute next chase stage: 0 (due day polite) | 3 (firm) | 7 (final)
// PRODUCT CONTROL: Status=Paid OR Status=Paused → skip entirely (cancels remaining 0/+3/+7).
// STOP reply / unsubscribe webhook set Status=Paused so this gate stops further sends.
// Defense-in-depth: Notes matching \bSTOP\b also skip (treat as opt-out even if Status still Open).
// Honor cooldown; claim key = InvoiceID + stage
const COOLDOWN_MS = 55 * 60 * 1000;
const STAGE_ORDER = [0, 3, 7];

function parseDue(d) {
  if (!d) return null;
  const s = String(d).trim().slice(0, 10);
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return null;
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

function todayUtcMidnight() {
  const n = new Date();
  return Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate());
}

function normalizeLastStage(v) {
  if (v === undefined || v === null || v === '' || String(v).toLowerCase() === 'none') return -1;
  const n = Number(v);
  return Number.isFinite(n) ? n : -1;
}

function notesHasStop(notes) {
  return /\bSTOP\b/i.test(String(notes || ''));
}

const out = [];
const today = todayUtcMidnight();

for (const item of items) {
  const row = item.json;
  const status = String(row.Status || '').trim();
  // Mandatory stop: Paid (settled) or Paused (STOP/opt-out) — no further stages
  if (status === 'Paid' || status === 'Paused') continue;
  // Defense-in-depth: Notes contain word STOP → skip (same as Paused)
  if (notesHasStop(row.Notes)) continue;

  const dueMs = parseDue(row.DueDate);
  if (dueMs === null) continue;

  const daysOverdue = Math.floor((today - dueMs) / 86400000);
  if (daysOverdue < 0) continue; // not due yet — no stage 0

  const lastStage = normalizeLastStage(row.LastStageSent);
  const lastSentAt = row.LastSentAt ? Date.parse(String(row.LastSentAt)) : NaN;
  if (Number.isFinite(lastSentAt) && Date.now() - lastSentAt < COOLDOWN_MS) continue;

  let next = null;
  for (const s of STAGE_ORDER) {
    if (daysOverdue >= s && lastStage < s) {
      next = s;
      break; // one stage per run
    }
  }
  if (next === null) continue;

  out.push({
    json: {
      InvoiceID: String(row.InvoiceID || ''),
      ClientName: String(row.ClientName || ''),
      ClientEmail: String(row.ClientEmail || ''),
      Amount: row.Amount,
      Currency: String(row.Currency || 'USD'),
      DueDate: String(row.DueDate || '').slice(0, 10),
      Status: status || 'Open',
      FromName: String(row.FromName || ''),
      ReplyTo: String(row.ReplyTo || ''),
      Notes: String(row.Notes || ''),
      row_number: row.row_number ?? row.rowNumber ?? undefined,
      nextStage: next,
      daysOverdue,
      claimAt: new Date().toISOString(),
    }
  });
}

return out;

// Build subject/body; HTML-escape all Sheet-driven fields. Do not return huge dumps for logging.
// M2 header injection: strip CR/LF from subject / replyTo / senderName / sendTo; validate single email.
function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function stripCrLf(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').trim();
}

function isSingleEmail(s) {
  const v = stripCrLf(s);
  // Single addr only — reject commas, spaces (except trimmed), header-ish chars
  if (!v || /[,\s;<>()]/.test(v)) return false;
  return /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(v);
}

const stage = Number($input.first().json.nextStage);
const j = $input.first().json;
const name = esc(j.ClientName);
const amount = esc(j.Amount);
const currency = esc(j.Currency);
const due = esc(j.DueDate);
const inv = esc(j.InvoiceID);
const fromName = esc(stripCrLf(j.FromName || 'Billing'));

const rawTo = stripCrLf(j.ClientEmail);
if (!isSingleEmail(rawTo)) {
  // Refuse send — bad/injected recipient
  return [];
}
const replyToRaw = stripCrLf(j.ReplyTo || '');
const replyTo = replyToRaw && isSingleEmail(replyToRaw) ? replyToRaw : '';

const templates = {
  0: {
    subject: `Friendly reminder: invoice ${stripCrLf(j.InvoiceID)} is due today`,
    html: `<p>Hi ${name},</p>
<p>Just a quick, friendly reminder that invoice <strong>${inv}</strong> for <strong>${amount} ${currency}</strong> is due today (${due}).</p>
<p>If you've already paid, thank you — you can ignore this note. Otherwise, whenever you have a moment to send payment, it's appreciated.</p>
<p>Thanks so much,<br>${fromName}</p>
<p style="color:#666;font-size:12px;">This is a payment reminder for invoice ${inv}. Reply to this email if you have questions.</p>
<p style="color:#666;font-size:12px;"><strong>Reply STOP</strong> to this email to pause reminders for this invoice.</p>`
  },
  3: {
    subject: `Follow-up: invoice ${stripCrLf(j.InvoiceID)} is 3 days past due`,
    html: `<p>Hi ${name},</p>
<p>I wanted to follow up on invoice <strong>${inv}</strong> for <strong>${amount} ${currency}</strong> (due ${due}). It looks like payment hasn't landed yet.</p>
<p>Could you confirm when payment will be sent, or let me know if anything is blocking it on your side?</p>
<p>Happy to help,<br>${fromName}</p>
<p style="color:#666;font-size:12px;">Payment reminder for invoice ${inv}. If this was paid already, please reply so we can mark it Paid and stop reminders.</p>
<p style="color:#666;font-size:12px;"><strong>Reply STOP</strong> to this email to pause reminders for this invoice.</p>`
  },
  7: {
    subject: `Final notice: invoice ${stripCrLf(j.InvoiceID)} is 7 days overdue`,
    html: `<p>Hi ${name},</p>
<p>This is a final reminder that invoice <strong>${inv}</strong> for <strong>${amount} ${currency}</strong> (due ${due}) is now 7 days overdue.</p>
<p>Please arrange payment when you can, or reply with an update so we can keep our records current.</p>
<p>Regards,<br>${fromName}</p>
<p style="color:#666;font-size:12px;">Final payment notice for invoice ${inv}. Reply if already paid or if you need a copy of the invoice.</p>
<p style="color:#666;font-size:12px;"><strong>Reply STOP</strong> to this email to pause reminders for this invoice.</p>`
  }
};

const t = templates[stage];
if (!t) return [];

const subject = stripCrLf(t.subject);
const senderName = stripCrLf(j.FromName || 'Billing');

// Pass only fields needed for Gmail — avoid retaining extra PII copies in side branches
return [{
  json: {
    InvoiceID: stripCrLf(j.InvoiceID),
    ClientEmail: rawTo,
    FromName: senderName,
    ReplyTo: replyTo,
    Notes: String(j.Notes || ''),
    nextStage: stage,
    subject,
    html: t.html,
  }
}];

// Gmail send failed after claim — revert claim OR pause so we don't silently skip the stage forever.
// Prefer: clear LastStageSent/LastSentAt (allow retry) AND note the error; if InvoiceID missing, no-op.
const j = $input.first().json || {};
const inv = String(j.InvoiceID || j.invoiceId || '').trim();
if (!inv) return [];
const stamp = new Date().toISOString();
const errMsg = String(j.error && (j.error.message || j.error) || j.message || 'Gmail send failed').slice(0, 200);
const prevNotes = String(j.Notes || '').trim();
const noteAppend = `[${stamp}] SEND_ERROR — claim reverted: ${errMsg}`;
const notes = prevNotes ? `${prevNotes} | ${noteAppend}` : noteAppend;
return [{
  json: {
    InvoiceID: inv,
    LastStageSent: 'none',
    LastSentAt: '',
    Notes: notes,
  }
}];
